package net.civeira.phylax.features.access.dcrinitialaccesstoken.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class DcrInitialAccessTokenCursorUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_dcr_initial_access_token_cursor_builder() {
    DcrInitialAccessTokenCursor cursor = DcrInitialAccessTokenCursor.builder().build();
    Assertions.assertFalse(cursor.getLimit().isPresent(),
        "Limit must be empty if cursor is build without it");
    Assertions.assertFalse(cursor.getSinceUid().isPresent(),
        "Since must be empty if cursor is build without it");
    cursor.setLimit(100);
    Assertions.assertEquals(100, cursor.getLimit().get(), "Limit must be the same as the assigned");
    cursor.setSinceUid("one");
    Assertions.assertEquals("one", cursor.getSinceUid().get(),
        "Since Uid must be the same as the assigned");
    Assertions.assertTrue(cursor.getOrder().isEmpty(), "The order must be empty");
    cursor.setOrder(List.of(DcrInitialAccessTokenOrder.DESCRIPTION_ASC,
        DcrInitialAccessTokenOrder.DESCRIPTION_DESC));
    Assertions.assertEquals(
        List.of(DcrInitialAccessTokenOrder.DESCRIPTION_ASC,
            DcrInitialAccessTokenOrder.DESCRIPTION_DESC),
        cursor.getOrder(), "The order must be the same that was assinged");
    Assertions.assertTrue(cursor.getSinceDescription().isEmpty(),
        "The value since for Description must be empty");
    cursor.setSinceDescription("one");
    Assertions.assertEquals("one", cursor.getSinceDescription().get(),
        "The value since for Description must be the same that was assinged");
  }
}
